SELECT analytics_order_facts.category, SUM(analytics_order_facts.gross_revenue) AS gross_revenue FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 2 AND analytics_order_facts.region = 'North' AND analytics_order_facts.channel = 'online' AND analytics_order_facts.customer_segment = 'enterprise' AND analytics_order_facts.category = 'category_06' GROUP BY analytics_order_facts.category ORDER BY gross_revenue DESC, analytics_order_facts.category ASC LIMIT 10
